argv:
$ErrorActionPreference='Stop';
$repo='E:\WebAIBridge';
$target='7351d8478600ceb1db50ea136efccb1c10a943c7';
$branch='agent/bridge-r42-live-control-plane-cutover-20261006';
& git.exe -C $repo fetch origin $branch;
if($LASTEXITCODE -ne 0){ throw "git fetch failed: $LASTEXITCODE" }
$dirty=@(& git.exe -C $repo status --porcelain);
if($LASTEXITCODE -ne 0){ throw "git status failed: $LASTEXITCODE" }
if($dirty.Count -gt 0){ throw "R42 recovery refuses dirty worktree" }
$current=(& git.exe -C $repo rev-parse HEAD).Trim();
$resolved=(& git.exe -C $repo rev-parse $target).Trim();
if($resolved -ne $target){ throw "target SHA mismatch: $resolved" }
& git.exe -C $repo switch --detach $target;
if($LASTEXITCODE -ne 0){ throw "git switch failed: $LASTEXITCODE" }
& powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $repo 'app\start.ps1') | Out-Null;
if($LASTEXITCODE -ne 0){ throw "start.ps1 failed: $LASTEXITCODE" }
$deadline=(Get-Date).AddSeconds(35);
$status=$null;
do{
  try{$status=Invoke-RestMethod -Uri 'http://127.0.0.1:17448/api/status' -TimeoutSec 2}catch{}
  if($status){break}
  Start-Sleep -Milliseconds 500
}while((Get-Date)-lt $deadline);
if(-not $status){ throw "Bridge did not become responsive after latest-green recovery" }
$lifecycle=$null;$control=$null;$r42=$null;
try{$lifecycle=Invoke-RestMethod -Uri 'http://127.0.0.1:17448/api/operator-lifecycle' -TimeoutSec 4}catch{}
try{$control=Invoke-RestMethod -Uri 'http://127.0.0.1:17448/api/projects/control-plane?inspect=0' -TimeoutSec 5}catch{}
try{$r42=Invoke-RestMethod -Uri 'http://127.0.0.1:17448/api/projects/control-plane/cutover-r42/status' -TimeoutSec 5}catch{}
$post=(& git.exe -C $repo rev-parse HEAD).Trim();
[pscustomobject]@{
  object='bridge.r42_partial_cutover_recovery.v1';
  preRecoveryHead=$current;
  targetSha=$target;
  postRecoveryHead=$post;
  bridgeResponsive=[bool]$status;
  statusObject=$status.object;
  lifecycle=$lifecycle;
  controlPlaneObject=$control.object;
  cutoverObject=$r42.object;
  cutoverState=$r42.cutoverState;
  providerMutationPerformed=$false;
  chatDeletionPerformed=$false
}|ConvertTo-Json -Depth 20 -Compress
